import unittest
from calc import apply_discount

class TestCalc(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(apply_discount(100, 10), 90)

    def test_discount_rounding(self):
        self.assertEqual(apply_discount(105, 10), 94)

if __name__ == '__main__':
    unittest.main()
